#include <Arduino.h>
#include <ArduinoJson.h>
#include <WebServer.h>
#include <WiFi.h>
#include <LittleFS.h>
#include "providers.h"
#include "config_store.h"
#include "artifacts.h"
#include "secrets.h"
#include "web_ui.h"
WebServer server(80); constexpr size_t MAX_BODY=18000; unsigned long lastReconnectAttempt=0;
File uploadFile; size_t uploadBytes=0; bool uploadFailed=false;
void sendJson(int s,const String& b){server.send(s,"application/json",b);} void sendError(int s,const String& m){JsonDocument d;d["error"]=m;String o;serializeJson(d,o);sendJson(s,o);}
void handleRoot(){server.send_P(200,"text/html",CHAT_ESP_HTML);} void handleHealth(){JsonDocument d;d["ok"]=true;d["wifi"]=WiFi.status()==WL_CONNECTED;d["ip"]=WiFi.localIP().toString();String o;serializeJson(d,o);sendJson(200,o);}
void handleConfig(){sendJson(200,configStatusJson());}
void handleConfigSave(){if(!server.hasArg("plain")||server.arg("plain").length()>2200)return sendError(400,"Configuration body missing or too large");JsonDocument d;if(deserializeJson(d,server.arg("plain")))return sendError(400,"Invalid JSON body");String provider=d["provider"]|"";bool ok=true;String submittedKey=d["apiKey"]|"";if(submittedKey.length())ok=saveProviderSecret(provider,submittedKey);if(d["ollamaUrl"].is<const char*>()){String url=d["ollamaUrl"].as<String>();if(url.length())ok=saveOllamaUrl(url)&&ok;}String defProvider,defModel;float temp;loadDefaults(defProvider,defModel,temp);if(d["defaultModel"].is<const char*>())defModel=d["defaultModel"].as<String>();if(d["defaultProvider"].is<const char*>())defProvider=d["defaultProvider"].as<String>();if(d["temperature"].is<float>()||d["temperature"].is<int>())temp=d["temperature"]|.7f;if(d["defaultProvider"].is<const char*>()||d["defaultModel"].is<const char*>()||d["temperature"].is<float>()||d["temperature"].is<int>())ok=saveDefaults(defProvider,defModel,constrain(temp,0.0f,2.0f))&&ok;if(!ok)return sendError(400,"Configuration value was invalid or could not be saved");sendJson(200,configStatusJson());}
void handleConfigDelete(){if(!server.hasArg("provider"))return sendError(400,"provider is required");String p=server.arg("provider");bool ok=p=="ollama"?deleteOllamaUrl():deleteProviderSecret(p);if(!ok)return sendError(400,"Unknown provider or nothing to delete");sendJson(200,configStatusJson());}
void handleModels(){if(!server.hasArg("provider"))return sendError(400,"provider is required");String p=server.arg("provider");Serial.printf("GET models provider=%s\n",p.c_str());auto r=fetchModels(p);if(!r.ok)return sendError(r.status,r.error);sendJson(200,r.payload);}
void handleChat(){if(!server.hasArg("plain")||server.arg("plain").length()>MAX_BODY)return sendError(400,"Request body missing or too large");JsonDocument d;if(deserializeJson(d,server.arg("plain")))return sendError(400,"Invalid JSON body");String p=d["provider"]|"",m=d["model"]|"";JsonArray msgs=d["messages"].as<JsonArray>();if(!p.length()||!m.length()||msgs.isNull())return sendError(400,"provider, model, and messages are required");String mj;serializeJson(msgs,mj);float t=d["temperature"]|.7f;t=constrain(t,0.0f,2.0f);Serial.printf("POST chat provider=%s model=%s messages=%u\n",p.c_str(),m.c_str(),(unsigned)msgs.size());auto r=generateChat(p,m,mj,t);if(!r.ok)return sendError(r.status,r.error);sendJson(200,r.payload);}
void handleAgent(){if(!server.hasArg("plain")||server.arg("plain").length()>MAX_BODY)return sendError(400,"Request body missing or too large");JsonDocument d;if(deserializeJson(d,server.arg("plain")))return sendError(400,"Invalid JSON body");String p=d["provider"]|"",m=d["model"]|"";JsonArray msgs=d["messages"].as<JsonArray>();if(!p.length()||!m.length()||msgs.isNull())return sendError(400,"provider, model, and messages are required");String mj;serializeJson(msgs,mj);float t=constrain(d["temperature"]|.4f,0.0f,2.0f);auto r=generateAgentPlan(p,m,mj,t);if(!r.ok)return sendError(r.status,r.error);sendJson(200,r.payload);}
void handleArtifacts(){sendJson(200,artifactsListJson());}
void handleArtifactUploadChunk(){HTTPUpload& u=server.upload();if(u.status==UPLOAD_FILE_START){uploadFailed=false;uploadBytes=0;LittleFS.remove("/.upload.tmp");uploadFile=LittleFS.open("/.upload.tmp",FILE_WRITE);if(!uploadFile)uploadFailed=true;}else if(u.status==UPLOAD_FILE_WRITE){if(uploadFailed||uploadBytes+u.currentSize>MAX_ARTIFACT_BYTES){uploadFailed=true;return;}size_t n=uploadFile.write(u.buf,u.currentSize);uploadBytes+=n;if(n!=u.currentSize)uploadFailed=true;}else if(u.status==UPLOAD_FILE_END){if(uploadFile)uploadFile.close();}}
void handleArtifactUpload(){String name=server.arg("name");if(!artifactNameSafe(name)){LittleFS.remove("/.upload.tmp");return sendError(400,"Unsafe artifact name");}if(uploadFailed||!LittleFS.exists("/.upload.tmp")){LittleFS.remove("/.upload.tmp");return sendError(uploadBytes>MAX_ARTIFACT_BYTES?413:507,"Artifact upload failed or storage is full");}String dest=artifactPath(name);LittleFS.remove(dest);if(!LittleFS.rename("/.upload.tmp",dest)){LittleFS.remove("/.upload.tmp");return sendError(507,"Not enough artifact storage");}sendJson(201,artifactsListJson());}
void handleArtifactDownload(){String name=server.arg("name"),mime;File file;if(!openArtifact(name,file,mime))return sendError(404,"Artifact not found");server.sendHeader("Content-Disposition","attachment; filename=\""+name+"\"");server.streamFile(file,mime);file.close();}
void handleArtifactDelete(){String name=server.arg("name");if(!artifactNameSafe(name))return sendError(400,"Unsafe artifact name");if(!deleteArtifact(name))return sendError(404,"Artifact not found");sendJson(200,artifactsListJson());}
void connectWiFi(){WiFi.mode(WIFI_STA);WiFi.setAutoReconnect(true);WiFi.begin(WIFI_SSID,WIFI_PASSWORD);Serial.printf("Connecting to Wi-Fi: %s\n",WIFI_SSID);for(int i=0;i<30&&WiFi.status()!=WL_CONNECTED;++i){delay(500);Serial.print('.');}Serial.println();if(WiFi.status()==WL_CONNECTED){Serial.printf("CHATESP_URL_BEGINhttp://%s/CHATESP_URL_END\n",WiFi.localIP().toString().c_str());}else Serial.println("Wi-Fi connection failed; check secrets.h");}
void setup(){Serial.begin(115200);delay(300);configStoreBegin();if(!artifactsBegin())Serial.println("LittleFS mount failed");connectWiFi();server.on("/",HTTP_GET,handleRoot);server.on("/api/health",HTTP_GET,handleHealth);server.on("/api/config",HTTP_GET,handleConfig);server.on("/api/config",HTTP_POST,handleConfigSave);server.on("/api/config/key",HTTP_DELETE,handleConfigDelete);server.on("/api/models",HTTP_GET,handleModels);server.on("/api/chat",HTTP_POST,handleChat);server.on("/api/agent",HTTP_POST,handleAgent);server.on("/api/artifacts",HTTP_GET,handleArtifacts);server.on("/api/artifacts",HTTP_DELETE,handleArtifactDelete);server.on("/api/artifacts/upload",HTTP_POST,handleArtifactUpload,handleArtifactUploadChunk);server.on("/api/artifacts/download",HTTP_GET,handleArtifactDownload);server.begin();Serial.println("HTTP server started");} void loop(){server.handleClient();if(WiFi.status()!=WL_CONNECTED&&millis()-lastReconnectAttempt>10000){lastReconnectAttempt=millis();WiFi.reconnect();}delay(2);}
